import React from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';

const Ins_P4 = () => {
  const context = useOutletContext();
  const { data: insuranceData, setter: setInsuranceData } = context?.ins || {};
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ins" links={["Claims", "Risk", "Policies", "Ledger"]} />
      <div className="summary-box">
        <h3>Distributed Settlement Ledger</h3>
        <div style={{ fontFamily: 'monospace', padding: '1rem', backgroundColor: '#f1f5f9', borderRadius: '4px', marginTop: '1rem' }}>
          {resumeData ? `[TRANSACTION] Commit complete. Record processing delay traced at: ${resumeData.latency || 0}ms` : "[STANDBY] Pipeline empty."}
        </div>
      </div>
    </div>
  );
};
export default Ins_P4;
